export const LANDING_CSS = "\nhtml[data-ghf-mode=\"night\"]{\n  color-scheme: dark;\n  --wiki-bg: #101418;\n  --wiki-paper: #202122;\n  --wiki-text: #eaecf0;\n  --wiki-muted: #a7acb1;\n  --wiki-border: #54595d;\n  --wiki-soft-border: #72777d;\n  --wiki-link: #8ab4f8;\n  --wiki-visited: #c0a5e8;\n  --wiki-control: #27292d;\n  --wiki-control-border: #72777d;\n  --wiki-table-head: #303338;\n  --wiki-table-alt: #27292d;\n  --assured: #202d25;\n  --assured-mark: #344d39;\n  --notassured: #30291d;\n  --notassured-mark: #5c4829;\n}\n.visually-hidden{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\nmain.landing{max-width:60rem}\nmain.landing details{border:1px solid var(--wiki-soft-border);border-radius:4px;background:var(--wiki-paper);margin:.5rem 0}\nmain.landing details>summary{cursor:pointer;padding:.65rem .8rem;font-weight:600;list-style-position:inside;overflow-wrap:anywhere}\nmain.landing details>summary:hover{background:var(--wiki-table-head)}\nmain.landing details>*:not(summary){margin-left:.8rem;margin-right:.8rem}\nmain.landing details details{border-color:var(--wiki-soft-border);margin:.4rem 0}\nmain.landing .landing-block{border-left:4px solid #1F3D2B}\nhtml[data-ghf-mode=\"night\"] main.landing .landing-block{border-left-color:#C9B6FF}\n.wiki-menu .menu-root{border-left:4px solid #C9B6FF}\n.wiki-menu a{display:block;padding:.45rem .2rem;border-bottom:1px solid var(--wiki-soft-border);overflow-wrap:anywhere}\n.wiki-menu details>div{padding-bottom:.4rem}\n.landing-search{display:flex;gap:.4rem;margin:.6rem 0 1rem}\n.landing-search input{flex:1;min-width:0;max-width:none;padding:.55rem;border:1px solid var(--wiki-control-border);border-radius:4px;background:var(--wiki-paper);color:var(--wiki-text)}\n.video-frame{position:relative;width:100%;aspect-ratio:16/9;margin:.2rem 0 .8rem}\n.video-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0}\nmain.landing figure{margin:.4rem 0}\nmain.landing video{width:100%;height:auto;background:#000}\nmain.landing figcaption{font-size:.85rem;color:var(--wiki-muted)}\n#ghf-parcel-tube-map>div:first-child{font-size:.8rem;letter-spacing:.06em;color:var(--wiki-muted);margin:.4rem 0}\nmain.landing p,main.landing li,main.landing div{overflow-wrap:anywhere}\n.ev-scroll{overflow-x:auto;max-width:100%}\n.ghf-ev-table{border-collapse:collapse;width:100%}\n.ghf-ev-table th,.ghf-ev-table td,.ghf-version-table th,.ghf-version-table td{border:1px solid var(--wiki-soft-border);padding:.4rem;vertical-align:top;text-align:left}\n.ghf-ev-table th{width:28%;background:var(--wiki-table-head)}\n.research-addendum{border-top:2px solid #1F3D2B;margin-top:1.5rem;padding-top:.5rem}\n.site-footer{font-size:.8rem}\n.yt-facade{position:absolute;inset:0;width:100%;height:100%;padding:0;border:0;background:#000;cursor:pointer}\n.yt-facade img{width:100%;height:100%;object-fit:cover;display:block}\n.yt-play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:68px;height:48px;border-radius:12px;background:#c4302b;color:#fff;font-size:22px;line-height:48px;text-align:center}\n.article>h1{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n";
